select public.prepify_load_bank('Physics', 5, $j$[["Which state of matter required a large force for deformation",["Solid","Liquid","Gas","Plasma"],"A",5,1,"d92a0eadfd82",0],["When a tennis racket hits a ball the shape of ball is distorted and regain its original shape this property is",["Pressure","Deformation","Elasticity","Density"],"C",5,1,"4e6d885ccdd2",0],["A girl is playing with clay and after pressing it is completely deformed we said this material as",["Elastic","Plastic","Liquid","Gas"],"B",5,1,"52d05311883d",0],["If the applied force exceeds the limit of proportionality in hooks law force and extension are no longer directly positional and the graph become",["Straight","Curve","Proportional","None of these"],"B",5,1,"14cc121c2bca",0],["A teacher wears high-heeled shoes one day and flat shoes the next day. Which shoes exert more pressure on the floor?",["Heel shoes","Flat shoes","Both have same","Both have no pressure"],"A",5,1,"a9b27055fdd0",0],["Flat shoes exert much less pressure than high heels because their area is",["Small","Large","Equal","No Area"],"B",5,1,"970eb5de8002",0],["A suction cup sticks to a wall easily due to",["Water pressure","Solid pressure","Atmospheric pressure","Liquid pressure"],"C",5,1,"c930c31ec60a",0],["At sea level the atmosphere will push down mercury in the tube and make it rise up in a tube to a height of approximately",["29.92 mm","560 mm","670 mm","760 mm"],"D",5,1,"7f9ad79a8e05",0],["The height of Mount Everest from the sea level is approximately equal to",["4.4 km","6.8 km","8.8 km","9.4 km"],"C",5,1,"6a62e7a5e252",0],["Galvanometer meter is a device in which hooks law is applicable for which purpose this device is used",["Charge","Current","Emf","All of them"],"B",5,1,"f7106fc09e77",0],["If the mass of a person sitting on a chair is doubled what would be the effect on pressure on chair",["Double","Four times","Three times","Half"],"A",5,1,"35bbafc12944",0],["The unit of pressure which is used in metrology and whether maps is",["Tar","Newton","Bar","Pascal"],"C",5,1,"99d202daaf78",0],["The liquid barometer works on a principal of",["Hydrostatic equilibrium","Stable equilibrium","Unstable equilibrium","Neutral equilibrium"],"A",5,1,"506d9b753720",0],["If we are climbing a mushkpuri track we feel suffocation this is due to",["Low atmospheric pressure","High atmospheric pressure","Zero atmospheric pressure","Due to more oxygen"],"A",5,1,"3595db18b6da",0],["The atmospheric pressure is decreases with height due to decrease in",["Power","Energy","Density","Force"],"C",5,1,"e314815297df",0],["If we have two containers one is filled with water and other is filled with Mercury and we place a stone in each container one after another the change in liquid pressure is due to",["Gravity","Depth","Color","Density"],"D",5,1,"e8ba4ac541e0",0],["When you dive in the sea, the force exerted on you by the pressure of the water acts",["Parallel","Perpendicular","Anti parallel","None of these"],"B",5,1,"ff7b961f36f0",0],["In a device in which pressure is applicable by a force on unit area . Which law describe this",["Newton's law","Pascal's law","Archimedes principal","All of these"],"B",5,1,"a0cd528b1d01",0],["A scuba diver goes deep into the sea to see marine life. The high pressure the diver experiences is due to",["Density","Volume","Gravity","Depth"],"D",5,1,"66742fa24631",0],["If the force applied on the brake pedal of a car is doubled over the same area, the pressure",["Half","Three time","Five times","Double"],"D",5,1,"621600f3c843",0],["In a DG cement factory there is a chiller power plant filled with oil if the engineers want to check the pressure of oil which device would be suitable",["Barometer","Manometer","Thermometer","Voltmeter"],"B",5,1,"7dbbc77ce738",0],["One bar is the unit of atmospheric pressure how many pascal are there in one bar",["1 x 10²","1 x10 ⁵","1x10 ⁶","1x 10 ⁸"],"B",5,1,"1e177f2992f4",0],["A sudden fall in the reading of a barometer usually indicates",["Dry weather","Storm","High liquid pressure","Expansion of Mercury"],"B",5,1,"b34590284f7f",0],["Three holes are drilled at different heights in a can full of water. Water spurts out fastest and furthest from which hole?",["Lower","Upper","Middle","All"],"A",5,1,"0c2314ab1e39",0],["Three holes are drilled at different heights in a can full of water. Water spurts out slowest and nearest from which hole?",["Upper","Middle","Lower","All"],"A",5,1,"1f5d1077839a",0],["Which of the following is an example of an elastic material?",["Clay","Dough","Stretched spring","Plasticine"],"C",3,0,"a265f192f455",0],["Beyond the elastic limit, a material:",["Always breaks immediately","Returns completely to original shape","Does not fully regain its original dimensions","Loses mass"],"C",3,0,"2b009e5381e8",0],["The correct mathematical expression of Hooke's law is:",["F= x/k","F= −kx","F= k /x","F= kx²"],"B",3,0,"abdf2daaf5f1",0],["The SI unit of spring constant is:",["N","Pa","N/m","kg/m³"],"C",3,0,"c2fe4a3750e9",0],["The slope of a force-extension graph gives:",["Pressure","Density","Spring constant","Weight"],"C",3,0,"92aa420dd05f",0],["Hooke’s law is obeyed up to:",["Limit of proportionality","Plastic limit","Breaking point","Yield point"],"A",3,0,"569e2dac1358",0],["A spring extends 4 cm under a force of 20 N. Under 40 N, the extension will be:",["2 cm","4 cm","8 cm","16 cm"],"C",3,0,"21bf2202539d",0],["The maximum stress a material can withstand before fracture is:",["Elastic stress","Ultimate stress","Pressure stress","Hydrostatic stress"],"B",3,0,"bfd14ac8c19a",0],["The SI unit of pressure is:",["Newton","Joule","Pascal","Watt"],"C",3,0,"e47c49ca0219",0],["1 Pascal equals:",["1 N/m²","1 N/m","1 kg/m²","1 J/m²"],"A",3,0,"2f30f911c721",0],["Pressure increases when:",["Area increases","Force decreases","Force increases on same area","Mass decreases"],"C",3,0,"5fcc11bfebc2",0],["A balloon bursts easily when pierced by a pin because:",["Pin is heavy","Pin applies high pressure on small area","Ballo